#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Implements PROTOCOL.md version 1 revision 1:
  * strict schema/bounds validation,
  * path normalization (IXP removal, prepend collapse, loop detection),
  * simultaneous peripheral peeling with round numbers,
  * exact joint inference over ternary core-link variables via bucket
    elimination on the supplied elimination order (induced width <= 4),
  * triple-minimum legitimacy score plus full valley-free path diagnostic.

Standard library only; one JSON document in, one JSON document out.
"""
import json
import re
import sys
from fractions import Fraction
from math import gcd

MAX_BYTES = 4194304
MAX_ASN = 4294967295
MAX_RIB = 2000
MAX_PRIORS = 2000
MAX_DECLARED = 2000
MAX_QUERIES = 512
MAX_IXPS = 1024
MAX_PATH_LEN = 64
MAX_RIB_LEN_SUM = 40000
MAX_COUNT = 1000000
MAX_WEIGHT = 1000000
MAX_RIB_LINKS = 4096
MAX_CORE = 64
MAX_WIDTH = 4

TOP_KEYS = frozenset(('version', 'ixps', 'rib', 'priors', 'declared', 'order',
                      'queries'))
RELS = ('c2p', 'p2p', 'p2c')
ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,64}')
UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
UNIFORM_F = (1.0 / 3.0, 1.0 / 3.0, 1.0 / 3.0)

# g table: rows L (c2p, p2p, p2c), columns R.  Flat index L*3+R.
GTAB = (0, 0, 1,
        1, 1, 2,
        1, 1, 2)

POW3 = [1]
for _i in range(12):
    POW3.append(POW3[-1] * 3)


class Invalid(Exception):
    """Raised for any input outside the schema or the stated bounds."""


# --------------------------------------------------------------------------
# parsing and validation
# --------------------------------------------------------------------------

def _pairs_hook(items):
    out = {}
    for key, value in items:
        if key in out:
            raise Invalid('duplicate key')
        out[key] = value
    return out


def _reject_float(_text):
    raise Invalid('non integer number')


def _reject_const(text):
    raise Invalid('non finite constant')


def parse_document(raw):
    if len(raw) > MAX_BYTES:
        raise Invalid('input too large')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('bad utf-8')
    try:
        return json.loads(text, object_pairs_hook=_pairs_hook, parse_int=int,
                          parse_float=_reject_float,
                          parse_constant=_reject_const)
    except Invalid:
        raise
    except Exception:
        raise Invalid('bad json')


def need_dict(value):
    if type(value) is not dict:
        raise Invalid('object expected')
    return value


def need_list(value):
    if type(value) is not list:
        raise Invalid('array expected')
    return value


def need_text(value):
    if type(value) is not str:
        raise Invalid('string expected')
    return value


def exact_keys(record, names):
    if len(record) != len(names):
        raise Invalid('key count')
    for name in names:
        if name not in record:
            raise Invalid('missing key')
    return record


def need_int(value, low, high):
    if type(value) is not int or value < low or value > high:
        raise Invalid('integer out of range')
    return value


def need_asn(value):
    return need_int(value, 1, MAX_ASN)


def need_asn_path(value):
    path = need_list(value)
    if len(path) > MAX_PATH_LEN:
        raise Invalid('path too long')
    for asn in path:
        need_asn(asn)
    return path


def need_link(value):
    link = need_list(value)
    if len(link) != 2:
        raise Invalid('link size')
    a = need_asn(link[0])
    b = need_asn(link[1])
    return a, b


def canon(a, b):
    return (a, b) if a < b else (b, a)


def validate(data):
    if type(data) is not dict:
        raise Invalid('top level')
    if frozenset(data.keys()) != TOP_KEYS:
        raise Invalid('top level keys')
    if type(data['version']) is not int or isinstance(data['version'], bool):
        raise Invalid('version type')
    if data['version'] != 1:
        raise Invalid('version value')

    ixp_list = need_list(data['ixps'])
    if len(ixp_list) > MAX_IXPS:
        raise Invalid('too many ixps')
    ixps = set()
    for asn in ixp_list:
        need_asn(asn)
        if asn in ixps:
            raise Invalid('duplicate ixp')
        ixps.add(asn)

    rib_list = need_list(data['rib'])
    if len(rib_list) > MAX_RIB:
        raise Invalid('too many rib records')
    rib = []
    length_sum = 0
    for record in rib_list:
        need_dict(record)
        exact_keys(record, ('path', 'count'))
        path = need_asn_path(record['path'])
        count = need_int(record['count'], 1, MAX_COUNT)
        length_sum += len(path)
        if length_sum > MAX_RIB_LEN_SUM:
            raise Invalid('rib too long')
        rib.append((path, count))

    prior_list = need_list(data['priors'])
    if len(prior_list) > MAX_PRIORS:
        raise Invalid('too many priors')
    priors = {}
    for record in prior_list:
        need_dict(record)
        exact_keys(record, ('link', 'weights'))
        a, b = need_link(record['link'])
        if a == b:
            raise Invalid('self prior')
        weights = need_list(record['weights'])
        if len(weights) != 3:
            raise Invalid('weights size')
        for weight in weights:
            need_int(weight, 0, MAX_WEIGHT)
        total = weights[0] + weights[1] + weights[2]
        if total <= 0:
            raise Invalid('weights sum')
        key = canon(a, b)
        if key in priors:
            raise Invalid('duplicate prior')
        vec = (Fraction(weights[0], total), Fraction(weights[1], total),
               Fraction(weights[2], total))
        priors[key] = vec if a < b else (vec[2], vec[1], vec[0])

    declared_list = need_list(data['declared'])
    if len(declared_list) > MAX_DECLARED:
        raise Invalid('too many declarations')
    declared = {}
    for record in declared_list:
        need_dict(record)
        exact_keys(record, ('link', 'rel'))
        a, b = need_link(record['link'])
        rel = need_text(record['rel'])
        if rel not in RELS:
            raise Invalid('relationship')
        key = canon(a, b)
        if key in declared:
            raise Invalid('duplicate declaration')
        slot = RELS.index(rel)
        vec = [Fraction(0)] * 3
        vec[slot] = Fraction(1)
        vec = tuple(vec)
        declared[key] = vec if a < b else (vec[2], vec[1], vec[0])

    order_list = need_list(data['order'])
    order = []
    for item in order_list:
        a, b = need_link(item)
        if a >= b:
            raise Invalid('order orientation')
        order.append((a, b))

    query_list = need_list(data['queries'])
    if len(query_list) > MAX_QUERIES:
        raise Invalid('too many queries')
    queries = []
    seen_ids = set()
    for record in query_list:
        need_dict(record)
        exact_keys(record, ('id', 'path', 'threshold'))
        qid = need_text(record['id'])
        if ID_RE.fullmatch(qid) is None:
            raise Invalid('query id')
        if qid in seen_ids:
            raise Invalid('duplicate query id')
        seen_ids.add(qid)
        path = need_asn_path(record['path'])
        threshold = need_list(record['threshold'])
        if len(threshold) != 2:
            raise Invalid('threshold size')
        num = need_int(threshold[0], 0, MAX_WEIGHT)
        den = need_int(threshold[1], 1, MAX_WEIGHT)
        if num > den:
            raise Invalid('threshold order')
        queries.append((qid, path, Fraction(num, den)))

    return ixps, rib, priors, declared, order, queries


# --------------------------------------------------------------------------
# normalization and peeling
# --------------------------------------------------------------------------

def normalize(path, ixps):
    out = []
    for asn in path:
        if asn in ixps:
            continue
        if out and out[-1] == asn:
            continue
        out.append(asn)
    return out


def has_loop(path):
    return len(set(path)) != len(path)


def aggregate(rib, ixps):
    counts = {}
    for path, count in rib:
        clean = normalize(path, ixps)
        if len(clean) < 2 or has_loop(clean):
            continue
        key = tuple(clean)
        counts[key] = counts.get(key, 0) + count
    return counts


def peel(paths):
    """Return (round_of, final_paths).  round_of maps removed link -> round."""
    round_of = {}
    current = paths
    round_no = 0
    while current:
        flags = {}
        for path in current:
            first = path[0]
            last = path[-1]
            for i in range(len(path) - 1):
                a = path[i]
                b = path[i + 1]
                key = (a, b) if a < b else (b, a)
                flag = flags.get(key)
                if flag is None:
                    flag = flags[key] = [True, True]
                u = key[0]
                v = key[1]
                if flag[0] and u != first and u != last:
                    flag[0] = False
                if flag[1] and v != first and v != last:
                    flag[1] = False
        marked = set()
        for key, flag in flags.items():
            if flag[0] or flag[1]:
                marked.add(key)
        if not marked:
            break
        round_no += 1
        for key in marked:
            round_of[key] = round_no
        trimmed = {}
        for path, count in current.items():
            size = len(path)
            start = 0
            stop = size
            a = path[0]
            b = path[1]
            if ((a, b) if a < b else (b, a)) in marked:
                start = 1
            a = path[size - 2]
            b = path[size - 1]
            if ((a, b) if a < b else (b, a)) in marked:
                stop = size - 1
            if stop - start >= 2:
                key = path[start:stop]
                trimmed[key] = trimmed.get(key, 0) + count
        current = trimmed
    return round_of, current


# --------------------------------------------------------------------------
# exact joint inference
# --------------------------------------------------------------------------

def build_factors(core_paths, var_of):
    """phi_e tables.  Returns list of (scope tuple, table list of ints)."""
    groups = {}
    for path, count in core_paths.items():
        size = len(path)
        for i in range(size - 1):
            a = path[i]
            b = path[i + 1]
            if a < b:
                key = (a, b)
                forward = True
            else:
                key = (b, a)
                forward = False
            if forward:
                left = (path[i - 1], a) if i > 0 else None
                right = (b, path[i + 2]) if i + 2 < size else None
            else:
                left = (path[i + 2], b) if i + 2 < size else None
                right = (a, path[i - 1]) if i > 0 else None
            if left is None:
                lit_l = (0, -1, False)
            else:
                x, y = left
                lit_l = (1, var_of[canon(x, y)], x > y)
            if right is None:
                lit_r = (0, 2, False)
            else:
                x, y = right
                lit_r = (1, var_of[canon(x, y)], x > y)
            slot = groups.get(key)
            if slot is None:
                slot = groups[key] = {}
            slot[(lit_l, lit_r)] = slot.get((lit_l, lit_r), 0) + count

    factors = []
    scopes = {}
    for key in sorted(groups):
        table_groups = groups[key]
        ctx = []
        for (lit_l, lit_r) in table_groups:
            if lit_l[0] == 1 and lit_l[1] not in ctx:
                ctx.append(lit_l[1])
            if lit_r[0] == 1 and lit_r[1] not in ctx:
                ctx.append(lit_r[1])
        me = var_of[key]
        ctx = sorted(set(ctx) - set([me]))
        scope = tuple([me] + ctx)
        scopes[key] = scope
        width = len(scope)
        size = POW3[width]
        digits = [[(idx // POW3[j]) % 3 for idx in range(size)]
                  for j in range(width)]
        center = digits[0]
        positions = {}
        for j in range(1, width):
            positions[scope[j]] = j
        table = [0] * size
        for (lit_l, lit_r), count in table_groups.items():
            if lit_l[0] == 0:
                left = None
                lconst = lit_l[1]
            else:
                col = digits[positions[lit_l[1]]]
                left = [2 - d for d in col] if lit_l[2] else col
                lconst = -1
            if lit_r[0] == 0:
                right = None
                rconst = lit_r[1]
            else:
                col = digits[positions[lit_r[1]]]
                right = [2 - d for d in col] if lit_r[2] else col
                rconst = -1
            if left is None and right is None:
                want = GTAB[lconst * 3 + rconst]
                for idx in range(size):
                    if center[idx] == want:
                        table[idx] += count
            elif left is None:
                for idx in range(size):
                    if center[idx] == GTAB[lconst * 3 + right[idx]]:
                        table[idx] += count
            elif right is None:
                for idx in range(size):
                    if center[idx] == GTAB[left[idx] * 3 + rconst]:
                        table[idx] += count
            else:
                for idx in range(size):
                    if center[idx] == GTAB[left[idx] * 3 + right[idx]]:
                        table[idx] += count
        factors.append((scope, table))
    return factors, scopes


def reduce_factors(factors):
    """Divide every potential by its integer gcd (keeps marginals, shrinks Z)."""
    out = []
    for scope, table in factors:
        divisor = 0
        for value in table:
            divisor = gcd(divisor, value)
        if divisor == 0:
            return None
        if divisor > 1:
            table = [value // divisor for value in table]
        out.append((scope, table))
    return out


def _product_table(bucket, allvars, digs, size):
    tab = [1] * size
    positions = {}
    for j, var in enumerate(allvars):
        positions[var] = j
    for scope, table in bucket:
        idxs = [0] * size
        for j, var in enumerate(scope):
            col = digs[positions[var]]
            weight = POW3[j]
            idxs = [ix + dd * weight for ix, dd in zip(idxs, col)]
        tab = [t * table[ix] for t, ix in zip(tab, idxs)]
    return tab


def partition_value(factors, order_vars):
    """Plain bucket elimination; returns the exact partition Z as an int."""
    active = [(scope, table, -1) for scope, table in factors]
    total = 1
    for v in order_vars:
        bucket = []
        rest = []
        for item in active:
            if v in item[0]:
                bucket.append(item)
            else:
                rest.append(item)
        if not bucket:
            continue
        scope_set = set()
        for item in bucket:
            scope_set.update(item[0])
        scope_set.discard(v)
        neigh = sorted(scope_set)
        allvars = neigh + [v]
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        tab = _product_table([(s, t) for s, t, _ in bucket], allvars, digs,
                             size)
        step = size // 3
        lam = [tab[n] + tab[n + step] + tab[n + 2 * step] for n in range(step)]
        if neigh:
            rest.append((tuple(neigh), lam, len(active)))
        else:
            total *= lam[0]
        active = rest
    return total


def infer_joint(factors, order_vars, count):
    """Exact joint inference: bucket elimination plus elimination-tree pass.

    Returns (Z, marginals) with marginals[v] the three unnormalized weights.
    """
    m = count
    if m == 0:
        return 1, []
    var_bucket = {}
    for i, v in enumerate(order_vars):
        var_bucket[v] = i
    active = [(scope, table, -1) for scope, table in factors]
    local = [None] * m
    child_msgs = [None] * m
    up_vars = [None] * m
    up_tab = [None] * m
    sep_vars = [None] * m
    sep_tab = [None] * m
    children = [[] for _ in range(m)]

    for i, v in enumerate(order_vars):
        bucket = []
        rest = []
        for item in active:
            if v in item[0]:
                bucket.append(item)
            else:
                rest.append(item)
        scope_set = set()
        for item in bucket:
            scope_set.update(item[0])
        scope_set.discard(v)
        neigh = sorted(scope_set)
        allvars = neigh + [v]
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        tab = _product_table([(s, t) for s, t, _ in bucket], allvars, digs,
                             size)
        step = size // 3
        lam = [tab[n] + tab[n + step] + tab[n + 2 * step] for n in range(step)]
        local[i] = [(s, t) for s, t, src in bucket if src < 0]
        child_msgs[i] = [(s, t) for s, t, src in bucket if src >= 0]
        up_vars[i] = allvars
        up_tab[i] = tab
        sep_vars[i] = neigh
        sep_tab[i] = lam
        if neigh:
            rest.append((tuple(neigh), lam, i))
            parent = m
            for x in neigh:
                if var_bucket[x] < parent:
                    parent = var_bucket[x]
            children[parent].append(i)
        active = rest

    total = 1
    for i in range(m):
        if not sep_vars[i]:
            total *= sep_tab[i][0]

    marginals = [None] * m
    incoming = [None] * m
    for i in range(m - 1, -1, -1):
        allvars = up_vars[i]
        neigh = sep_vars[i]
        step = POW3[len(neigh)]
        tab = up_tab[i]
        msg = incoming[i]
        if msg is None:
            belief = tab
        else:
            belief = [t * msg[a % step] for a, t in enumerate(tab)]
        marginals[order_vars[i]] = [sum(belief[t * step:(t + 1) * step])
                                    for t in range(3)]
        kids = children[i]
        if not kids:
            continue
        size = POW3[len(allvars)]
        digs = [[(a // POW3[j]) % 3 for a in range(size)]
                for j in range(len(allvars))]
        positions = {}
        for j, var in enumerate(allvars):
            positions[var] = j
        for j in kids:
            sep_j = sep_vars[j]
            facs = list(local[i])
            for item in child_msgs[i]:
                facs.append(item)
            drop = sep_tab[j]
            facs = [(s, t) for s, t in facs if t is not drop]
            send = _product_table(facs, allvars, digs, size)
            if msg is not None:
                send = [t * msg[a % step] for a, t in enumerate(send)]
            out = [0] * POW3[len(sep_j)]
            if sep_j:
                idxs = [0] * size
                for k, var in enumerate(sep_j):
                    col = digs[positions[var]]
                    weight = POW3[k]
                    idxs = [ix + dd * weight for ix, dd in zip(idxs, col)]
                for a, value in enumerate(send):
                    if value:
                        out[idxs[a]] += value
            else:
                out[0] = sum(send)
            incoming[j] = out
    return total, marginals


# --------------------------------------------------------------------------
# scoring
# --------------------------------------------------------------------------

def full_score(vectors):
    """Sum of probabilities of c2p* p2c* and c2p* p2p p2c* type sequences."""
    a0 = 1.0
    a1 = 0.0
    b0 = 1.0
    b1 = 0.0
    b2 = 0.0
    for up, peer, down in vectors:
        na0 = a0 * up
        na1 = (a0 + a1) * down
        nb0 = b0 * up
        nb1 = b0 * peer
        nb2 = (b1 + b2) * down
        a0 = na0
        a1 = na1
        b0 = nb0
        b1 = nb1
        b2 = nb2
    return a0 + a1 + b1 + b2


def score_query(path, threshold, lookup):
    size = len(path)
    if size <= 2:
        return 1.0, 1.0, None, False
    exact = []
    floats = []
    for i in range(size - 1):
        a = path[i]
        b = path[i + 1]
        vec = lookup(canon(a, b))
        if a > b:
            vec = (vec[2], vec[1], vec[0])
        exact.append(vec)
        floats.append((float(vec[0]), float(vec[1]), float(vec[2])))
    best = None
    witness = 0
    for i in range(size - 2):
        up = exact[i][0]
        down = exact[i + 1][2]
        value = up + down - up * down
        if best is None or value < best:
            best = value
            witness = i
    return float(best), full_score(floats), witness, best < threshold


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def solve(data):
    ixps, rib, priors, declared, order, queries = validate(data)

    paths = aggregate(rib, ixps)

    all_links = set()
    for path in paths:
        for i in range(len(path) - 1):
            all_links.add(canon(path[i], path[i + 1]))
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid('too many rib links')

    round_of, core_paths = peel(paths)
    core_links = sorted(all_links - set(round_of))
    if len(core_links) > MAX_CORE:
        raise Invalid('too many core links')

    var_of = {}
    for index, key in enumerate(core_links):
        var_of[key] = index
    count = len(core_links)

    order_vars = []
    if len(order) != count:
        raise Invalid('order length')
    seen = set()
    for pair in order:
        if pair in seen:
            raise Invalid('duplicate order entry')
        seen.add(pair)
        if pair not in var_of:
            raise Invalid('order entry not core')
        order_vars.append(var_of[pair])

    factors = []
    scopes = {}
    if count:
        factors, scopes = build_factors(core_paths, var_of)
        reduced = reduce_factors(factors)
        if reduced is None:
            return {'error': 'zero-partition'}
        factors = reduced
        # structural width validation on the scope graph
        adjacency = [set() for _ in range(count)]
        for scope in scopes.values():
            for x in scope:
                for y in scope:
                    if x < y:
                        adjacency[x].add(y)
                        adjacency[y].add(x)
        live = [set(neigh) for neigh in adjacency]
        for v in order_vars:
            neigh = live[v]
            if len(neigh) > MAX_WIDTH:
                raise Invalid('order width')
            neigh = sorted(neigh)
            for x in neigh:
                for y in neigh:
                    if x < y:
                        live[x].add(y)
                        live[y].add(x)
            for x in neigh:
                live[x].discard(v)
            live[v] = set()

    if count:
        total, marginals = infer_joint(factors, order_vars, count)
        if total == 0:
            return {'error': 'zero-partition'}
    else:
        total, marginals = 1, []

    core_prob = {}
    for key in core_links:
        nums = marginals[var_of[key]]
        core_prob[key] = (Fraction(nums[0], total), Fraction(nums[1], total),
                          Fraction(nums[2], total))

    links_out = []
    for key in sorted(all_links):
        rnd = round_of.get(key, 0)
        if rnd == 0:
            vec = core_prob[key]
        else:
            vec = priors.get(key, UNIFORM)
        links_out.append({'link': [key[0], key[1]], 'round': rnd,
                          'prob': [float(vec[0]), float(vec[1]),
                                   float(vec[2])]})

    def lookup(key):
        vec = declared.get(key)
        if vec is not None:
            return vec
        vec = core_prob.get(key)
        if vec is not None:
            return vec
        vec = priors.get(key)
        if vec is not None:
            return vec
        return UNIFORM

    queries_out = []
    for qid, raw_path, threshold in queries:
        path = normalize(raw_path, ixps)
        if has_loop(path):
            queries_out.append({'id': qid, 'path': path, 'status': 'loop',
                                'score': None, 'full': None, 'witness': None,
                                'leaked': None})
            continue
        score, full, witness, leaked = score_query(path, threshold, lookup)
        queries_out.append({'id': qid, 'path': path, 'status': 'ok',
                            'score': score, 'full': full, 'witness': witness,
                            'leaked': leaked})

    return {'version': 1, 'links': links_out, 'queries': queries_out}


def run():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b''
    try:
        data = parse_document(raw)
        answer = solve(data)
    except Invalid:
        answer = {'error': 'invalid'}
    except (ValueError, TypeError, KeyError, IndexError, ZeroDivisionError,
            ArithmeticError, RecursionError):
        answer = {'error': 'invalid'}
    sys.stdout.write(json.dumps(answer, allow_nan=False))
    sys.stdout.write('\n')


if __name__ == '__main__':
    run()
