        for (lit_l, lit_r), count in groups[var].items():
            if lit_l[0] == 0:
                left = None
                lconst = lit_l[1]
            else:
                col = digits[positions[lit_l[1]]]
                left = [2 - d for d in col] if lit_l[2] else col
                lconst = 0
            if lit_r[0] == 0:
                right = None
                rconst = lit_r[1]
            else:
                col = digits[positions[lit_r[1]]]
                right = [2 - d for d in col] if lit_r[2] else col
                rconst = 0
            if left is None and right is None:
                want = GTAB[lconst * 3 + rconst]
                for idx in range(size):
                    if center[idx] == want:
                        table[idx] += count
            elif left is None:
                for idx in range(size):
                    if center[idx] == GTAB[lconst * 3 + right[idx]]:
                        table[idx] += count
            elif right is None:
                for idx in range(size):
                    if center[idx] == GTAB[left[idx] * 3 + rconst]:
                        table[idx] += count
            else:
                for idx in range(size):
                    if center[idx] == GTAB[left[idx] * 3 + right[idx]]:
                        table[idx] += count
        factors.append((scope, table))
    return factors


def check_width(scopes, order_vars, count):
    """Validate the promised elimination width on the scope graph."""
    live = [set() for _ in range(count)]
    for scope in scopes:
        for x in scope:
            for y in scope:
                if x < y:
                    live[x].add(y)
                    live[y].add(x)
