# scoring
# --------------------------------------------------------------------------

def normalize_vector(nums, den):
    """Shrink an integer probability vector by its common divisor."""
    divisor = gcd(gcd(nums[0], nums[1]), nums[2])
    if divisor > 1:
        return ((nums[0] // divisor, nums[1] // divisor, nums[2] // divisor),
                den // divisor)
    return (nums, den)


def full_score(vectors):
    """Sum of probabilities of c2p* p2c* and c2p* p2p p2c* type sequences."""
    a0 = 1.0
    a1 = 0.0
    b0 = 1.0
    b1 = 0.0
    b2 = 0.0
    for up, peer, down in vectors:
        na0 = a0 * up
        na1 = (a0 + a1) * down
        nb0 = b0 * up
        nb1 = b0 * peer
        nb2 = (b1 + b2) * down
        a0 = na0
        a1 = na1
        b0 = nb0
        b1 = nb1
        b2 = nb2
    return a0 + a1 + b1 + b2


def score_query(path, thr_num, thr_den, lookup):
    """Exact triple minimum and valley-free diagnostic for one query path.

    All probabilities are kept as integer numerator/denominator pairs and
    scaled to one common denominator, so the minimum, the witness and the
    threshold comparison are exact without rational normalization.
    """
    size = len(path)
    if size <= 2:
        return 1.0, 1.0, None, False
    links = size - 1
    vectors = []
    common = 1
    for i in range(links):
        a = path[i]
        b = path[i + 1]
        nums, den = lookup(canon(a, b))
        if a > b:
            nums = (nums[2], nums[1], nums[0])
        vectors.append((nums, den))
        common = lcm(common, den)
    scaled = [[n * (common // den) for n in nums] for nums, den in vectors]
    best = None
    witness = 0
    for i in range(links - 1):
        up = scaled[i][0]
        down = scaled[i + 1][2]
        value = (up + down) * common - up * down
        if best is None or value < best:
            best = value
            witness = i
    square = common * common
    floats = [(nums[0] / den, nums[1] / den, nums[2] / den)
              for nums, den in vectors]
    return (best / square, full_score(floats), witness,
            best * thr_den < thr_num * square)


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def solve(data):
    ixps, rib, priors, declared, order, queries = validate(data)

    paths = aggregate(rib, ixps)

    all_links = set()
    for path in paths:
        for i in range(len(path) - 1):
            all_links.add(canon(path[i], path[i + 1]))
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid('too many rib links')

    round_of, core_paths = peel(paths)
    core_links = sorted(all_links - set(round_of))
    if len(core_links) > MAX_CORE:
        raise Invalid('too many core links')

    var_of = {}
    for index, key in enumerate(core_links):
        var_of[key] = index
    count = len(core_links)

    order_vars = []
    if len(order) != count:
        raise Invalid('order length')
    seen = set()
    for pair in order:
        if pair in seen:
            raise Invalid('duplicate order entry')
        seen.add(pair)
        if pair not in var_of:
            raise Invalid('order entry not core')
        order_vars.append(var_of[pair])

    factors = []
    if count:
        groups, scopes = collect_groups(core_paths, var_of, count)
        # all structural validation precedes the model outcome
        check_width(scopes, order_vars, count)
        factors = reduce_factors(build_tables(groups, scopes))
        if factors is None:
            return {'error': 'zero-partition'}

    if count:
        total, marginals = infer_joint(factors, order_vars, count)
        if total == 0:
            return {'error': 'zero-partition'}
        for nums in marginals:
            if nums[0] + nums[1] + nums[2] != total:
                marginals = naive_marginals(factors, order_vars, count)
                break
    else:
        total, marginals = 1, []

    core_prob = {}
    for key in core_links:
        core_prob[key] = normalize_vector(tuple(marginals[var_of[key]]), total)

    links_out = []
    for key in sorted(all_links):
        rnd = round_of.get(key, 0)
        if rnd == 0:
            nums, den = core_prob[key]
        else:
            nums, den = priors.get(key, UNIFORM_INT)
        links_out.append({'link': [key[0], key[1]], 'round': rnd,
                          'prob': [nums[0] / den, nums[1] / den,
                                   nums[2] / den]})

    def lookup(key):
        vec = declared.get(key)
        if vec is not None:
            return vec
        vec = core_prob.get(key)
        if vec is not None:
            return vec
        return priors.get(key, UNIFORM_INT)

    queries_out = []
    for qid, raw_path, thr_num, thr_den in queries:
        path = normalize(raw_path, ixps)
        if has_loop(path):
            queries_out.append({'id': qid, 'path': path, 'status': 'loop',
                                'score': None, 'full': None, 'witness': None,
                                'leaked': None})
            continue
        score, full, witness, leaked = score_query(path, thr_num, thr_den,
                                                   lookup)
        queries_out.append({'id': qid, 'path': path, 'status': 'ok',
                            'score': score, 'full': full, 'witness': witness,
                            'leaked': leaked})

    return {'version': 1, 'links': links_out, 'queries': queries_out}


def run():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b''
    try:
        data = parse_document(raw)
        answer = solve(data)
    except Invalid:
        answer = {'error': 'invalid'}
    except (ValueError, TypeError, KeyError, IndexError, ZeroDivisionError,
            ArithmeticError, RecursionError):
        answer = {'error': 'invalid'}
    sys.stdout.write(json.dumps(answer, allow_nan=False))
    sys.stdout.write('\n')


if __name__ == '__main__':
    run()

